import React from "react";
import PropTypes from "prop-types";

import { required, number } from "./ValidationUtil";
import { Button } from "@traveloka/soya-components";
import DropdownInput from "./DropdownInput";
import { NotificationManager, Label } from "@traveloka/soya-components";
import TextInput from "./TextInput";

import * as style from "./CommonRule.styles";

class CommonRuleModal extends React.Component {
  constructor(props) {
    super(props);
    if (props.mode === "create") {
      this.state = {
        name: "",
        description: "",
        priority: "0",
        enabled: "true",
      };
    } else {
      this.state = {
        name: props.rule.name || "",
        description: props.rule.description || "",
        priority: props.rule.priority || "0",
        enabled: props.rule ? props.rule.enabled.toString() : "true",
      };
    }
  }

  render() {
    const { name, description, priority, enabled } = this.state;
    const { mode } = this.props;
    const enabledItems = [
      { value: "true", label: "True" },
      { value: "false", label: "False" },
    ];
    return (
      <div>
        <div>
          <Label>{"Name"}</Label>
          <TextInput
            value={name}
            placeholder={"Rule Name"}
            name="name"
            onChange={this.handleInputChange}
            validators={[required]}
          />
        </div>
        <div>
          <Label>{"Description"}</Label>
          <TextInput
            value={description}
            placeholder={"Description"}
            name="description"
            onChange={this.handleInputChange}
            validators={[]}
          />
        </div>
        <div>
          <Label>{"Priority"}</Label>
          <TextInput
            value={priority}
            placeholder={"Priority"}
            name="priority"
            onChange={this.handleInputChange}
            validators={[required, number]}
          />
        </div>
        <div>
          <Label>{"Enabled"}</Label>
          <DropdownInput
            value={enabled}
            name="enabled"
            onChange={this.handleSelectChange}
            items={enabledItems}
          />
        </div>
        <div className={style.modalFooter}>
          <Button onClick={this.handleCancel} color="link">
            {"Close"}
          </Button>
          <Button onClick={this.handleSave} color="blue">
            {mode === "edit" ? "Save" : "Add"}
          </Button>
        </div>
      </div>
    );
  }

  handleInputChange = (name, value, isValid) => {
    if (isValid) {
      const stateObj = {};
      stateObj[name] = value;
      this.setState(stateObj);
    }
  };

  handleSelectChange = (name, value) => {
    this.setState({ enabled: value });
  };

  handleCancel = () => {
    const { onCancel } = this.props;
    onCancel();
  };

  handleSave = () => {
    const { onSave } = this.props;
    const { name, description, priority } = this.state;
    let { enabled } = this.state;
    if (name && priority && enabled) {
      enabled = enabled === "true";
      onSave({
        name,
        description,
        priority,
        enabled,
      });
    } else {
      NotificationManager.showError("Please fix input");
    }
  };
}

CommonRuleModal.propTypes = {
  onSave: PropTypes.func,
  onCancel: PropTypes.func,
  mode: PropTypes.oneOf(["create", "edit", "duplicate"]),
  rule: PropTypes.shape({
    name: PropTypes.string,
    description: PropTypes.string,
    priority: PropTypes.number,
    enabled: PropTypes.bool,
  }),
};

export default CommonRuleModal;
